-- Whole-relation estimate changes send immediate and transaction-end invalidations.
CREATE SEQUENCE analyze_checks;
CREATE TYPE analyze_choice AS ENUM('a');
CREATE DOMAIN analyze_checked AS analyze_choice CHECK(nextval('analyze_checks')>0);
CREATE TABLE analyze_anchor(id integer,value text);
CREATE TABLE analyze_unrelated(id integer);
INSERT INTO analyze_anchor VALUES(1,'a');
INSERT INTO analyze_unrelated VALUES(1);
SET check_function_bodies=off;
CREATE FUNCTION analyze_body() RETURNS analyze_checked[] LANGUAGE sql SET search_path=public AS
  $$SELECT '{a}'::analyze_checked[] FROM analyze_anchor LIMIT 1$$;
SET check_function_bodies=on;
ALTER SEQUENCE analyze_checks RESTART WITH 1;
SELECT analyze_body();
SELECT 'initial',last_value FROM analyze_checks;
ANALYZE analyze_unrelated;
SELECT analyze_body();
SELECT 'unrelated',last_value FROM analyze_checks;
ANALYZE analyze_anchor;
SELECT analyze_body();
SELECT 'first_analyze',last_value FROM analyze_checks;
ANALYZE analyze_anchor;
SELECT analyze_body();
SELECT 'same_estimates',last_value FROM analyze_checks;
BEGIN;
INSERT INTO analyze_anchor VALUES(2,'b');
ANALYZE analyze_anchor;
SELECT analyze_body();
SELECT 'before_rollback',last_value FROM analyze_checks;
ROLLBACK;
SELECT analyze_body();
SELECT 'after_rollback',last_value FROM analyze_checks;
ANALYZE analyze_anchor;
SELECT analyze_body();
SELECT 'restored_counts',last_value FROM analyze_checks;
BEGIN;
SAVEPOINT before_analyze;
INSERT INTO analyze_anchor VALUES(3,'c');
ANALYZE analyze_anchor;
SELECT analyze_body();
SELECT 'before_savepoint_rollback',last_value FROM analyze_checks;
ROLLBACK TO before_analyze;
SELECT analyze_body();
SELECT 'after_savepoint_rollback',last_value FROM analyze_checks;
COMMIT;
ANALYZE analyze_anchor;
SELECT analyze_body();
SELECT 'restored_after_savepoint',last_value FROM analyze_checks;
BEGIN;
INSERT INTO analyze_anchor VALUES(4,'d');
ANALYZE analyze_anchor;
SELECT analyze_body();
SELECT 'before_commit',last_value FROM analyze_checks;
COMMIT;
SELECT analyze_body();
SELECT 'after_commit',last_value FROM analyze_checks;
UPDATE analyze_anchor SET value='longer';
ANALYZE analyze_anchor;
SELECT analyze_body();
SELECT 'changed_column_samples',last_value FROM analyze_checks;
INSERT INTO analyze_anchor VALUES(5,'e');
CREATE INDEX analyze_index ON analyze_anchor(id);
SELECT analyze_body();
SELECT 'index_refreshed',last_value FROM analyze_checks;
ANALYZE analyze_anchor;
SELECT analyze_body();
SELECT 'analyze_after_index',last_value FROM analyze_checks;
DROP FUNCTION analyze_body();
DROP TABLE analyze_anchor,analyze_unrelated;
DROP DOMAIN analyze_checked;
DROP TYPE analyze_choice;
DROP SEQUENCE analyze_checks;
